CREATE VIEW std_all_inventory AS (SELECT igdb_id, opencritic_id, game_title, genre_raw, theme_raw, mode_raw, perspective_raw, acquisition_source_raw, storage_location_raw, NULL AS organization_folder_raw, play_status_raw, owned_flag, difficulty_rating, base_length_hours, full_completion_hours, file_size_gb, platform_name FROM std_ps5_inventory) UNION ALL ((SELECT NULL AS igdb_id, NULL AS opencritic_id, game_title, genre_raw, theme_raw, mode_raw, perspective_raw, acquisition_source_raw, storage_location_raw, NULL AS organization_folder_raw, play_status_raw, owned_flag, difficulty_rating, NULL AS base_length_hours, full_completion_hours, file_size_gb, platform_name FROM std_ps4_inventory) UNION ALL (SELECT NULL AS igdb_id, NULL AS opencritic_id, game_title, genre_raw, theme_raw, mode_raw, perspective_raw, acquisition_source_raw, storage_location_raw, organization_folder_raw, play_status_raw, owned_flag, difficulty_rating, NULL AS base_length_hours, full_completion_hours, file_size_gb, platform_name FROM std_wiiu_inventory));
